[11886] = {id=11886,name="Unusual Activity",level=1,requiredLevel=1,faction="both",expansion=0,zoneID=148,mapID=85,description="While celebration has its place, , some of us must look to graver matters. When the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.",objectivesText="Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon . Progress: What have you uncovered?",starts={{npcID=26221,x=0.62,y=0.678,zoneID=85},{npcID=26221,x=0.67,y=0.13,zoneID=1497},{npcID=26221,x=0.494,y=0.72,zoneID=1519},{npcID=26221,x=0.648,y=0.274,zoneID=1537},{npcID=26221,x=0.472,y=0.376,zoneID=1637},{npcID=26221,x=0.212,y=0.244,zoneID=1638},{npcID=26221,x=0.622,y=0.492,zoneID=1657},{npcID=26221,x=0.688,y=0.426,zoneID=3487},{npcID=26221,x=0.432,y=0.258,zoneID=3557},{npcID=26221,x=0.604,y=0.308,zoneID=3703}},ends={{npcID=25324,x=0.146,y=0.226,zoneID=331}},coords={x=0.62,y=0.678,source="quest_giver",zoneID=85},questType="world",worldTaskTitle="Unusual Activity"},
[11964] = {id=11964,name="Incense for the Summer Scorchlings",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=9042,mapID=84,description="Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue. With each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire. Would you like to honor a scorchling, ? Take this summer incense and bring it to any summer scorchling . Appease the little fire spirit, and it may reward you.",objectivesText="The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement. Progress: A fiery salutations to you, honored <class>. Welcome to this hallowed ground of the Midsummer Fire Festival.",starts={{npcID=16817,x=0.496,y=0.72,zoneID=1519},{npcID=16817,x=0.64,y=0.258,zoneID=1537},{npcID=16817,x=0.622,y=0.486,zoneID=1657},{npcID=16817,x=0.414,y=0.252,zoneID=3557},{npcID=16817,x=0.612,y=0.322,zoneID=3703}},ends={{npcID=26401,x=0.538,y=0.452,zoneID=1},{npcID=26401,x=0.19,y=0.56,zoneID=3},{npcID=26401,x=0.556,y=0.148,zoneID=4},{npcID=26401,x=0.738,y=0.544,zoneID=10},{npcID=26401,x=0.134,y=0.472,zoneID=11},{npcID=26401,x=0.434,y=0.626,zoneID=12},{npcID=26401,x=0.618,y=0.404,zoneID=15},{npcID=26401,x=0.434,y=0.822,zoneID=28},{npcID=26401,x=0.52,y=0.636,zoneID=33},{npcID=26401,x=0.324,y=0.412,zoneID=38},{npcID=26401,x=0.446,y=0.62,zoneID=40},{npcID=26401,x=0.25,y=0.532,zoneID=44},{npcID=26401,x=0.442,y=0.458,zoneID=45},{npcID=26401,x=0.682,y=0.606,zoneID=46},{npcID=26401,x=0.144,y=0.5,zoneID=47},{npcID=26401,x=0.752,y=0.436,zoneID=65},{npcID=26401,x=0.414,y=0.866,zoneID=67},{npcID=26401,x=0.548,y=0.526,zoneID=141},{npcID=26401,x=0.486,y=0.226,zoneID=148},{npcID=26401,x=0.868,y=0.418,zoneID=331},{npcID=26401,x=0.468,y=0.436,zoneID=357},{npcID=26401,x=0.338,y=0.604,zoneID=394},{npcID=26401,x=0.66,y=0.172,zoneID=405}