[55640] = {id=55640,name="Vision of Stormwind",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=15942,mapID=37,objectivesText="Complete the Vision of Stormwind.",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=152112,text="Vision of Stormwind completed"}},worldTaskTitle="Vision of Stormwind",db2QuestInfoID=135,db2QuestInfoName="Rare World Quest"},
[55716] = {id=55716,name="Uat-ka the Sun's Wrath",categories={"vignette"},flags={"tracking"},expansion=0,mapID=1527,questType="vignette",worldTaskTitle="Vignette - Uat-ka the Sun's Wrath",db2VignetteID=3624,db2VignetteName="Uat-ka the Sun's Wrath"},
[56308] = {id=56308,name="Assault: Aqir Unearthed",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our position is being overrun. The aqir are surging in greater numbers than I've ever seen! I'm not sure how long we'll be able to hold the line. We need you to drive them back!",objectivesText="Drive back the Aqir Assault in Uldum . Progress: Our men can only hold out so long.",ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},coords={mapID=1527,source="quest_giver",x=0.4,y=0.212},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Drive back the Aqir"}},worldTaskTitle="Assault: Aqir Unearthed",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[56402] = {id=56402,name="Wastewander Coins",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="It may be too late for some of our fallen brothers and sisters, but it is not too late to give solace to their families. Every Wastewander carries with them a unique coin, signifying their status as a member of our group. If you find any of these coins, please bring them to me and I will make sure they are properly returned to their next of kin.",objectivesText="Collect 6 Wastewander Coins . Progress: Do you have coins to return?",starts={{npcID=159560,x=0.4,y=0.452,zoneID=10833}},ends={{npcID=159560,x=0.4,y=0.452,zoneID=10833}},coords={x=0.4,y=0.452,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wastewander Coins"},
[56550] = {id=56550,name="Corpse Cleanup",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Our friends continue to fall as these terrible insects pour of their nests and attack our camps. It's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible. We can't allow our dead to be used as fertilizer for growing their disgusting eggs.",objectivesText="Burn 8 Egg-bearing corpses. Progress: We need to complete this task quickly and without delay.",starts={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},ends={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Corpse Cleanup"},
[56889] = {id=56889,name="Wounded Wastewanderers",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Ahh, my friend, have you returned to render additional aid? As you can see, we are still locked in battle with these creatures, with no end to their numbers in sight. This is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount. Please, assist any of our wounded that you find within the ruins.",objectivesText="Heal 6 Wastewander Laborers . Progress: Do you require additional bandages?",starts={{npcID=159820,x=0.28,y=0.634,zoneID=10833}},ends={{npcID=159820,x=0.28,y=0.634,zoneID=10833}},coords={x=0.28,y=0.634,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wounded Wastewanderers"},
[57157] = {id=57157,name="Assault: The Black Empire",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="It is just as the visions fortold. Dark forces have come to claim the Forge of Origination. They must be stopped, or all of Azeroth will meet its end!",objectivesText="Drive back the N'Zoth Assault in Uldum . Progress: The madness... it consumes!",ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={mapID=1527,source="quest_giver",x=0.546,y=0.328},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Drive back N'Zoth's Forces"}},worldTaskTitle="Assault: The Black Empire",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
