[57621] = {id=57621,name="Summoning Ritual",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,questType="world",worldTaskTitle="Summoning Ritual",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[57737] = {id=57737,name="Ramkahen Rescue",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. I fear the worst has happened to them. Please, if anyone is left alive within the city, tell them to come to Ramkahen.",objectivesText="Rescue 6 Mar'at Villagers .",starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Ramkahen Rescue"},
[57773] = {id=57773,name="Close to Tears",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. They have been but mere weaklings, clearly intended to test our defenses before the real forces arrive. If we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder. Find a way to close those portals!",objectivesText="Find and close 3 Void Tears in Uldum . Progress: Have you had any luck with the portals yet?",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Close to Tears"},
[57774] = {id=57774,name="Nine Lives",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting. Neferset have been spotted wandering the streets of their city to the south. This would normally be no cause for alarm, except the Neferset were completely wiped out. I must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!",objectivesText="Destroy 8 Neferset Denizens . Progress: Have you news of Neferset City?",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Nine Lives"},
[57968] = {id=57968,name="The Wastewandering Dead",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,description="Is there no end to these foul monsters!? I cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army. Destroy as many as you can, preferably with fire!",objectivesText="Kill 6 Wastewander Hosts . Progress: I hope you've been keeping count of your kills.",starts={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},ends={{npcID=159682,x=0.244,y=0.552,zoneID=10833}},coords={x=0.244,y=0.552,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="The Wastewandering Dead"},
[58010] = {id=58010,name="More Bits, More Bits!",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="We need more Aqir samples, $p. As many as you can get your hands on! I've made some fascinating discoveries already, but there's so much more to learn. With further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.",objectivesText="Collect 16 Aqir Bits . Progress: Have you obtained any additional samples?",starts={{npcID=161738,x=0.556,y=0.352,zoneID=10833}},ends={{npcID=161738,x=0.556,y=0.352,zoneID=10833}},coords={x=0.556,y=0.352,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="More Bits, More Bits!"},
[58146] = {id=58146,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance! A world of adventure awaits you beyond the walls of Mechagon City. When you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy. There will be many potential avenues of advancement available to you. Choose wisely, improve, and remember to share your data.",objectivesText="Meet Ambassador Moorgard at the Stormwind Embassy. Progress: Welcome to Stormwind, <race>.",starts={{npcID=159587,x=0.73,y=0.336,zoneID=10290}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},coords={x=0.73,y=0.336,source="quest_giver",zoneID=10290},questType="world",worldTaskTitle="For the Alliance"},
[58147] = {id=58147,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",objectivesText="Find Chromie in Stormwind City. Progress: So, how does Stormwind suit you?",starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=160600,x=0.624,y=0.298,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Stranger in a Strange Land"},
[58151] = {id=58151,name="Minions of N'Zoth",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers. Something must be done. Enter the darkness, , and strike down the enemy.",objectivesText="Defeat 20 minions of N'Zoth within the vision. Progress: The winds envelop us, comforting, calming... but beneath it all lurks a great, ever-present darkness.",starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Minions of N'Zoth"},
[58155] = {id=58155,name="A Hand in the Dark",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself. Thoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation. So many are lost to the darkness, unable to resist these temptations, but not all. Do what you can to preserve those that fight against the darkness. We mustn't allow them to fall.",objectivesText="Rescue 8 souls from the vision. Progress: It is best not to linger in darkness.",starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Hand in the Dark"},
[58156] = {id=58156,name="Vanquishing the Darkness",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="The darkness grows. The cycle continues. Do what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.",objectivesText="Repel N'Zoth's corruption within the vision. Progress: We both know what must be done.",starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Vanquishing the Darkness"},
[58167] = {id=58167,name="Preventative Measures",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach. Make your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.",objectivesText="Destroy 3 Void Portals within the vision. Progress: Darkness lurks beneath the waters.",starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Preventative Measures"},
[58168] = {id=58168,name="A Dark, Glaring Reality",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=12766,mapID=1527,description="Their eyes are upon us, , watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking. The fault is by no means your own. We should have suspected this was the case long ago. If we are to continue our efforts with meaningful expectations we must go undetected. Our old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.",objectivesText="Defeat 6 Darkglare Watchers within the vision. Progress: Seeing things more clearly?",starts={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},ends={{npcID=160252,x=0.842,y=0.516,zoneID=9105},{npcID=160252,x=0.566,y=0.318,zoneID=10833}},coords={x=0.842,y=0.516,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Dark, Glaring Reality"},
[58229] = {id=58229,name="A Rallying Cry",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers. Our forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale. Find the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.",objectivesText="Kill 3 rare minions of N'Zoth in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="A Rallying Cry"},
[58230] = {id=58230,name="Blind the Eyes",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance. The eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.",objectivesText="Kill 6 Foul Observers in the Akhenet Fields in Uldum . Progress: Is it done?",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Blind the Eyes"},
[58231] = {id=58231,name="Wisdom From Madness",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="In my visions I hear... voices... Their words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word. We will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.",objectivesText="Collect 10 Maddened Writings from Black Empire Cultists in Uldum . Progress: Have you found the writings?",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Wisdom From Madness"},
[58232] = {id=58232,name="Order Among Chaos",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited. However, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. I have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.",objectivesText="Kill 6 faceless minions of N'Zoth in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Order Among Chaos",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58233] = {id=58233,name="Twisted Corruptors",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. Like a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form. They must be eradicated.",objectivesText="Kill 10 fleshbeasts in Uldum .",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Twisted Corruptors"},
[58234] = {id=58234,name="Questionable Sourcing",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health. I have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption. If you could retrieve some samples of this for me, it could prove invaluable in our efforts.",objectivesText="Collect 8 Coalesced Corruption from slimes in Uldum . Progress: Have you acquired the reagent?",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Questionable Sourcing"},
[58235] = {id=58235,name="Anchors of the Black Empire",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from. However, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces. If we truly wish to stem the tide of this invasion, we must destroy the obelisks.",objectivesText="Destroy 6 Black Empire Obelisks in Uldum .",starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Anchors of the Black Empire"},
[58236] = {id=58236,name="Symbolic Destruction",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. Their mindless followers flock to these banners, worshipping them as unholy idols. Burn them down, and cleanse their taint from our lands.",objectivesText="Destroy 6 Banners of the Black Empire in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Symbolic Destruction"},
[58237] = {id=58237,name="Cleansing Uldum",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Every moment that N'Zoth's forces remain in Uldum , his corruption seeps further into the land itself. Even if we were to drive back his minions, the damage he has done to Uldum may be irreversible. We must seek out his corruption where it festers and eliminate it.",objectivesText="Destroy 6 Corruption Tumors in Uldum . Progress: We must put a stop to N'Zoth's Corruption.",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Cleansing Uldum"},
[58238] = {id=58238,name="Lost and Tormented",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. Our brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions. I know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.",objectivesText="Free 6 Ramkahen Citizens from Torment Cells within the Lost City of Tol'vir in Uldum .",starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Lost and Tormented"},
[58239] = {id=58239,name="Lessons in Brigandry",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days. One such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them. Find their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.",objectivesText="Loot 3 Black Empire Caches in Uldum . Progress: Found anything worthwhile?",starts={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.546,y=0.34,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Lessons in Brigandry"},
[58277] = {id=58277,name="Dark Deceivers",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=9105,mapID=1527,description="The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir. Though not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself. We must not allow their machinations to go unchecked.",objectivesText="Kill 8 K'thir minions in Uldum .",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Dark Deceivers"},
[58281] = {id=58281,name="Ancient Armaments",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes. Though the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts. Can you help?",objectivesText="Collect 10 pieces of Amathet Armor from armored Amathet tol'vir in Uldum . Progress: Have you returned with the armor?",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Ancient Armaments"},
[58282] = {id=58282,name="Down From the Sky",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous. You have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once. Will you help?",objectivesText="Kill 8 Amathet Bowmen in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Down From the Sky"},
[58283] = {id=58283,name="Blind Leading the Blind",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. Those that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning. They must be stopped.",objectivesText="Kill 8 Amathet priests in Uldum .",starts={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},ends={{npcID=155099,x=0.546,y=0.328,zoneID=10833}},coords={x=0.546,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Blind Leading the Blind"},
[58284] = {id=58284,name="Writs of the Sun King",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners. I would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. You seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.",objectivesText="Collect 6 Writs of the Sun King from Suntouched Amathet in Uldum . Progress: Have you found anything interesting?",starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Writs of the Sun King"},
[58285] = {id=58285,name="Unearthed Artifacts",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. I'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found! Of course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? Care to help?",objectivesText="Collect 6 Titan Artifacts in Uldum . Progress: Any luck with the titan artifacts ?",starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Unearthed Artifacts"},
[58286] = {id=58286,name="Far From Home",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. Fortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. We must take any opportunity we can to free them and return them to their homes.",objectivesText="Free 6 Enslaved Tol'vir in Uldum .",starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Far From Home"},
[58287] = {id=58287,name="A Smashing Plan",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. I don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical. Just don't tell the Explorers' League. I'll never hear the end of it.",objectivesText="Destroy 4 Amathet Idols and 2 Suntouched Obelisks in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="A Smashing Plan"},
[58288] = {id=58288,name="The Sun King's Chosen",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with. Seek out the strongest of their numbers and bring them down in front of their eyes. We will show them the strength of Uldum !",objectivesText="Defeat 3 rare Amathet enemies in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="The Sun King's Chosen"},
[58289] = {id=58289,name="Guarded Secrets",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them! Of course, that would be a lot easier if they weren't trying to kill us. If you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!",objectivesText="Loot 3 Amathet Caches in Uldum .",starts={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},ends={{npcID=155102,x=0.55,y=0.33,zoneID=10833}},coords={x=0.55,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Guarded Secrets"},
[58290] = {id=58290,name="Champions of the Amathet",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The soldiers of Ramkahen are hearty and reliable. I would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle. I don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.",objectivesText="Kill 6 elite Amathet enemies in Uldum .",starts={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},ends={{npcID=155096,x=0.548,y=0.33,zoneID=10833}},coords={x=0.548,y=0.33,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Champions of the Amathet",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58291] = {id=58291,name="Encroaching Poachers",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds. We need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.",objectivesText="Collect 6 Rugged Hyena Pelts from Amathet Hunters or by skinning hyenas in Uldum . Progress: Have you brought back the pelts?",starts={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},ends={{npcID=160957,x=0.546,y=0.34,zoneID=10833}},coords={x=0.546,y=0.34,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Encroaching Poachers"},
[58321] = {id=58321,name="Uncommon Core",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Our scouts have reported that the Amathet are constructing new titanic watchers. We had long thought this art was lost to the sands of time. It would appear we were mistaken. I needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum . We must unlock the secrets of their construction! The power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.",objectivesText="Collect a Titanic Core from an Ivory Watcher in Uldum . Progress: Have you obtained the core?",starts={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},ends={{npcID=155095,x=0.548,y=0.328,zoneID=10833}},coords={x=0.548,y=0.328,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Uncommon Core",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58742] = {id=58742,name="Retinus the Seeker",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,objectivesText="Defeat Grixis Tinypop in a pet battle.",starts={{x=0.62,y=0.319,mapID=1527}},ends={{x=0.62,y=0.319,mapID=1527}},coords={mapID=1527,x=0.62,y=0.319},questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2854,text="Defeat Retinus the Seeker"}},worldTaskTitle="Retinus the Seeker",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58743] = {id=58743,name="Dune Buggy",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,objectivesText="Defeat Grixis Tinypop in a pet battle.",starts={{x=0.355,y=0.316,mapID=1527}},ends={{x=0.355,y=0.316,mapID=1527}},coords={mapID=1527,x=0.355,y=0.316},questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2856,text="Defeat Aqir Sandcrawler"}},worldTaskTitle="Dune Buggy",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58744] = {id=58744,name="I Am The One Who Whispers",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,objectivesText="Defeat Grixis Tinypop in a pet battle.",starts={{x=0.617,y=0.544,mapID=1527}},ends={{x=0.617,y=0.544,mapID=1527}},coords={mapID=1527,x=0.617,y=0.544},questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2855,text="Defeat Whispers"}},worldTaskTitle="I Am The One Who Whispers",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58745] = {id=58745,name="Watch Where You Step",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=10833,mapID=1527,objectivesText="Defeat Grixis Tinypop in a pet battle.",starts={{x=0.576,y=0.436,mapID=1527}},ends={{x=0.576,y=0.436,mapID=1527}},coords={mapID=1527,x=0.576,y=0.436},questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2857,text="Defeat Blotto"}},worldTaskTitle="Watch Where You Step",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58776] = {id=58776,name="Hatching Problems",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long. The only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so. That's why I wish to conscript your services. Will you help?",objectivesText="Destroy 6 Aqir Egg Clusters in Uldum .",starts={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Hatching Problems"},
[58777] = {id=58777,name="Put Your Foot Down",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="You see that? Doesn't look like much, but believe it or not, those bugs grow out of these things. They're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities. If you happen to see any of them, do the world a favor and take your boot to 'em.",objectivesText="Squish 8 Aqir Larvae in Uldum .",starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Put Your Foot Down"},
[58778] = {id=58778,name="Getting Ahead",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place. I've got an idea to perk the troops back up, though. We need a trophy! See if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?",objectivesText="Collect 1 Goliath Trophy from Aqir Goliaths in Uldum . Progress: Show me what ya got!",starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Getting Ahead",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58779] = {id=58779,name="Taking the Skies",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air. I think we're going to have to thin them out on the ground before we can hope to gain aerial superiority. Can I count on you to lend a hand?",objectivesText="Kill 15 flying Aqir in Uldum . Progress: How fares the bug smashing?",starts={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159920,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Taking the Skies"},
[58780] = {id=58780,name="Heralds of the Hive",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic. My instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met. Are you up to the task?",objectivesText="Kill 5 Aqir Dominators in Uldum . Progress: What do you have to report?",starts={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=154443,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Heralds of the Hive",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58781] = {id=58781,name="Terrors from the Deep",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them. Our fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. I know that you have experience putting down great foes. I would like to ask you to do the same for us. After all, we can hardly help protect the forge if we've been decimated by some long-buried monster.",objectivesText="Defeat 3 rare Aqir enemies in Uldum .",starts={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Terrors from the Deep"},
[58782] = {id=58782,name="Things Left Behind",level=50,requiredLevel=50,faction="both",expansion=0,zoneID=10833,mapID=1527,description="The invading aqir forced the Wastewanders to flee many of our settlements in Uldum . In our haste to escape, much was left behind. I understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? You can keep anything of use to you, of course.",objectivesText="Collect 3 Wastewander Supplies from Infested Caches in Uldum . Progress: Were you able to find anything?",starts={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},ends={{npcID=159544,x=0.4,y=0.212,zoneID=10833}},coords={x=0.4,y=0.212,source="quest_giver",zoneID=10833},questType="world",worldTaskTitle="Things Left Behind"},
[60542] = {id=60542,name="Nathanos Blightcaller",level=50,requiredLevel=50,faction="none",expansion=0,zoneID=139,mapID=23,questType="world",worldTaskTitle="Nathanos Blightcaller",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[78177] = {id=78177,name="To Gilneas",level=70,requiredLevel=70,faction="alliance",expansion=0,zoneID=4706,mapID=217,description="The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised. However, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. Join me in retaking Gilneas.",objectivesText="Travel to Keel Harbor in the Ruins of Gilneas. Progress: Gilneas will be ours once more.",starts={{mapID=84,npcID=214538,x=0.339,y=0.155667}},ends={{mapID=21,npcID=210905,x=0.416,y=0.722}},coords={mapID=84,source="quest_giver",x=0.339,y=0.155667},questType="world",worldTaskTitle="To Gilneas"},
[78178] = {id=78178,name="To Gilneas",level=70,requiredLevel=70,faction="horde",expansion=0,zoneID=4706,mapID=217,description="<name>, we've received word of an offensive occurring soon in Gilneas. We have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city. We wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. Lilian and I want you to join us in this operation.",objectivesText="Travel to Gilneas in Eastern Kingdoms to assist with retaking Gilneas City for the Gilneans. Progress: Thank you for coming to help, <name>.",starts={{mapID=21,npcID=210965,x=0.428,y=0.726}},ends={{mapID=21,npcID=210905,x=0.416,y=0.722}},coords={mapID=21,source="quest_giver",x=0.428,y=0.726},questType="world",worldTaskTitle="To Gilneas"},
[78180] = {id=78180,name="A Crusade of Red",level=70,requiredLevel=70,faction="both",expansion=0,zoneID=4706,mapID=217,description="Calia will lead the Forsaken army in a distracting assault to the North. I'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops. There's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?",objectivesText="Kill 10 Scarlet Crusade Members in Aderic's Repose. Progress: These Scarlets are a blight upon the land.",starts={{mapID=21,npcID=210905,x=0.416,y=0.722}},ends={{mapID=21,npcID=210905,x=0.416,y=0.722}},coords={mapID=21,source="quest_giver",x=0.416,y=0.722},questType="world",worldTaskTitle="A Crusade of Red"},
[78181] = {id=78181,name="Aderic's Retort",level=70,requiredLevel=70,faction="both",expansion=0,zoneID=4706,mapID=217,description="The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. Too many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner! Take out their leader, and send them a message they won't soon forget.",objectivesText="Slay Consecrator Hennas in Aderic's Repose. Progress: Is she dead, <name>?",starts={{mapID=217,npcID=210904,x=0.5,y=0.4424}},ends={{mapID=217,npcID=212187,x=0.495,y=0.569}},coords={mapID=217,source="quest_giver",x=0.5,y=0.4424},questType="world",worldTaskTitle="Aderic's Retort"},
[78182] = {id=78182,name="Knee-High",level=70,requiredLevel=70,faction="both",expansion=0,zoneID=4706,mapID=217,description="Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city. Head through the tunnel to meet them. Take this torch, the way is infested with vermin. I'll ready our forces to storm the gate the moment it is opened.",objectivesText="Make your way through the secret tunnel in Aderic's Repose to Gilneas City.",starts={{mapID=217,npcID=212187,x=0.495,y=0.569}},ends={{mapID=21,npcID=210905,x=0.416,y=0.722}},coords={mapID=217,source="quest_giver",x=0.495,y=0.569},questType="world",worldTaskTitle="Knee-High"},
[78183] = {id=78183,name="Scarlet Blood",level=70,requiredLevel=70,faction="both",expansion=0,zoneID=4706,mapID=217,description="Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. We'll whittle their numbers down one by one.",objectivesText="Kill 12 Scarlet forces. Progress: Are you done?",starts={{mapID=21,npcID=210964,x=0.426,y=0.727}},ends={{mapID=21,npcID=210964,x=0.426,y=0.727}},coords={mapID=21,source="quest_giver",x=0.426,y=0.727},questType="world",worldTaskTitle="Scarlet Blood"},
[81886] = {id=81886,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1519,mapID=84,description="For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people. Will you be among the first to accept and visit their lands, learn their histories and walk amongst their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.",objectivesText="Meet Ambassador Moorgard at the Stormwind Embassy.",starts={{x=0.087,y=0.496,mapID=2322,npcID=221890}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},coords={mapID=84,source="quest_giver",x=0.530667,y=0.150667},questType="world",worldTaskTitle="For the Alliance"},
[81887] = {id=81887,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",objectivesText="Talk to Chromie in Stormwind City. Progress: Greetings, <name>.",starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=224806,x=0.56,y=0.174,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Stranger in a Strange Land"},
[81888] = {id=81888,name="For the Horde",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1637,mapID=85,description="For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people. Will you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.",objectivesText="Meet with Ambassador Blackguard at the Orgrimmar Embassy.",starts={{x=0.087,y=0.496,mapID=2322,npcID=221890}},ends={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},coords={mapID=85,source="quest_giver",x=0.395,y=0.794},questType="world",worldTaskTitle="For the Horde"},
[81889] = {id=81889,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1519,mapID=85,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Talk to Chromie . Progress: Greetings, <name>.",starts={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=224807,x=0.406,y=0.802,zoneID=1637}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="Stranger in a Strange Land"},
[82080] = {id=82080,name="More Torch Tossing",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=3557,mapID=84,description="Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you are timed and have a LOT more braziers to hit. Ready?",objectivesText="Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!",starts={{mapID=84,npcID=25975,x=0.4985,y=0.7205}},ends={{mapID=84,npcID=25975,x=0.4985,y=0.7205}},coords={mapID=84,source="quest_giver",x=0.4985,y=0.7205},questType="world",worldTaskTitle="More Torch Tossing"},
[82087] = {id=82087,name="Torch Tossing",level=1,requiredLevel=1,faction="alliance",expansion=0,zoneID=3557,mapID=84,description="So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! Stand near the bonfire and you'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers, then come back here... for your next lesson.",objectivesText="Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!",starts={{mapID=84,npcID=25975,x=0.4985,y=0.7205}},ends={{mapID=84,npcID=25975,x=0.4985,y=0.7205}},coords={mapID=84,source="quest_giver",x=0.4985,y=0.7205},questType="world",worldTaskTitle="Torch Tossing"},
[82105] = {id=82105,name="Torch Tossing",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=3487,mapID=88,description="So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! As you approach the bonfire you'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers then come back here... for your next lesson.",objectivesText="Win the torch tossing game, then speak with the Master Flame Eater . Progress: Quick! There's no time to waste!",starts={{mapID=18,npcID=26113,x=0.624,y=0.668}},ends={{mapID=18,npcID=26113,x=0.624,y=0.668}},coords={mapID=18,source="quest_giver",x=0.624,y=0.668},questType="world",worldTaskTitle="Torch Tossing"},
[82109] = {id=82109,name="More Torch Tossing",level=1,requiredLevel=1,faction="horde",expansion=0,zoneID=3487,mapID=88,description="Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you have a little more time and a LOT more braziers to hit. Ready?",objectivesText="Win the torch tossing game, then speak with the Master Flame Eater . Progress: Quick! There's no time to waste!",starts={{mapID=18,npcID=26113,x=0.624,y=0.668}},ends={{mapID=18,npcID=26113,x=0.624,y=0.668}},coords={mapID=18,source="quest_giver",x=0.624,y=0.668},questType="world",worldTaskTitle="More Torch Tossing"},
[82672] = {id=82672,name="Another Timely Invitation",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=84,description="The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris! There are all sorts of new activities to partake in that honor and remember what has transpired over the years. Head to Tanaris and join in the festivities.",objectivesText="Visit the celebration in Tanaris outside the Caverns of Time.",starts={{npcID=224334,x=0.498,y=0.71,zoneID=1519},{npcID=224419,x=0.478,y=0.78,zoneID=1637}},ends={{npcID=223877,x=0.628,y=0.506,zoneID=440}},coords={x=0.498,y=0.71,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Another Timely Invitation"},
[84236] = {id=84236,name="The Great Detective",level=10,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="Adventurer, thank the Light you are here. We have a missing guest. There was a detective who was investigating the case, but I have not heard back. Could you please check in with him?",objectivesText="Speak with Detective Jones.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="The Great Detective"},
[84334] = {id=84334,name="Warn the Detective",level=10,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="Welcome back, . I saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!",objectivesText="Warn Detective Jones about the shapeshifter.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440},{npcID=228661,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Warn the Detective"},
[84424] = {id=84424,name="Forward, to Adventure!",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description="We are free, . Free to do whatever it is we wish. Through the portal lies the rest of your life. A member of the bronze dragonflight will help you on your journey.",starts={{npcID=229075,x=0.43,y=0.898,zoneID=15510}},ends={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},coords={x=0.43,y=0.898,source="quest_giver",zoneID=15510},questType="world",worldTaskTitle="Forward, to Adventure!"},
[84563] = {id=84563,name="Toy Trouble",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=440,mapID=71,description="Adventurer, Maru is once again in need of your aid. She has an urgent matter that she would like to discuss with you.",objectivesText="Speak with Maru .",starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Toy Trouble"},
[84755] = {id=84755,name="The Final Toy",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=440,mapID=71,description="Maru discovered that one of her toys is now missing! Could this be related to the other missing toys that you previously helped her friends with?",objectivesText="Speak with Maru .",starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="The Final Toy"},
[85024] = {id=85024,name="Toy Trouble",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=440,mapID=71,description="Adventurer, Maru is once again in need of your aid. She has an urgent matter that she would like to discuss with you.",objectivesText="Speak with Maru .",starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Toy Trouble"},
[85026] = {id=85026,name="Where Legends are Made",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description="There's so much to catch you up on ! Where do you want to start?",objectivesText="Select a Timewalking Campaign from Chromie . Progress: Oooh, that one is my favorite!",starts={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},ends={{npcID=167032,x=0.56,y=0.172,zoneID=1519},{npcID=167032,x=0.408,y=0.8,zoneID=1637}},coords={x=0.56,y=0.172,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Where Legends are Made"},
[85042] = {id=85042,name="The Final Toy",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=440,mapID=71,description="Maru discovered that one of her toys is now missing! Could this be related to the other missing toys that you previously helped her friends with?",objectivesText="Speak with Maru .",starts={{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232405,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="The Final Toy"},
[85475] = {id=85475,name="Secret in the Sands",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=71,description="Welcome back. Maru is looking for you again. She says only you have the skills to help her with this task. Oh, don't worry about me. I'll be here... As always...",objectivesText="Speak with Maru .",starts={{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226684,x=0.632,y=0.524,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Secret in the Sands"},
[85502] = {id=85502,name="Festive Reflections",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=440,mapID=71,description="Oh good, you're back. I have my hands full here and Detective Jones has been asking for your help on some new case. Not that it seems to matter. For all the good we do for the guests, I think this line--if you can still call it that--has only grown longer! I should get back to it, and you should talk to Detective Jones.",objectivesText="Speak with Detective Jones.",starts={{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232407,x=0.63,y=0.502,zoneID=440},{npcID=232408,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},ends={{npcID=226796,x=0.61,y=0.506,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="world",worldTaskTitle="Festive Reflections"},
[86822] = {id=86822,name="One Final Relic",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="$p, I've asked the Sons of Lothar to meet us in the Burning Steppes near Blackrock Mountain. There's one more item we must recover there. We can depart as soon as you are ready.",objectivesText="Travel to the Burning Steppes and meet with the Sons of Lothar. Progress: Good trip?",starts={{npcID=240747,x=0.686,y=0.32,zoneID=45}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.686,y=0.32,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="One Final Relic"},
[86823] = {id=86823,name="The Dark Horde",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah! This Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains. If they haven't seen the truth by now, there is little hope for them but death.",objectivesText="Kill 12 soldiers of the Dark Horde.",starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="The Dark Horde"},
[86824] = {id=86824,name="None Left Standing",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="The one thing worse than seeing this Dark Horde here is their banners. It showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil. Burn down every one you find.",objectivesText="Burn 6 Dark Horde Banners. Progress: Got those banners dealt with, <name>?",starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="None Left Standing"},
[86825] = {id=86825,name="Faithful Servant, Faithless Cause",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="One of their lieutenants, Mar'kag , appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps. Taking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think. Faol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.",objectivesText="Defeat Mar'kag . Progress: Did you put a stop to Mar'kag , <name>?",starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237224,x=0.334,y=0.486,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Faithful Servant, Faithless Cause"},
[86826] = {id=86826,name="Nagosh the Scarred",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=51,mapID=36,description="The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost. He barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. I'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.",objectivesText="Defeat Nagosh the Scarred . Progress: Did ye put a stop to Nagosh?",starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Nagosh the Scarred"},
[86827] = {id=86827,name="Due Recognition",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=51,mapID=36,description="Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea. Defeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear? Head on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.",objectivesText="Retrieve Stone Guard Badges from the Dark Horde in Blackrock Mountain. Progress: Did ye get their badges, <name>?",starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Due Recognition"},
[86828] = {id=86828,name="Not Just a Troll's Bane",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on. Danath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.",objectivesText="Find Danath Trollbane .",starts={{npcID=237268,x=0.212,y=0.398,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Not Just a Troll's Bane"},
[86829] = {id=86829,name="A Landmark Moment",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="With their leader defeated and that third relic fragment found, we should regroup with the others back at Lothar's Statue, $p. I'll meet you there.",objectivesText="Meet the Sons of Lothar at Lothar's Statue.",starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=248263,x=0.368,y=0.508,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A Landmark Moment"},
[86830] = {id=86830,name="A True Horde of Dark Horde",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="The remaining Dark Horde forces are gathered here, $p. Many of them look to be untrained and new to the cause. Drive away the forces gathered here, and perhaps we can hope to see some peace in this region--for the first time in decades.",objectivesText="Defeat 12 Dark Horde troops and 3 Dark Horde Sergeants. Progress: You've made a good start, <name>, with Arator 's help.",starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A True Horde of Dark Horde"},
[86831] = {id=86831,name="Warriors Without a Warlord",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. Take them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed. And Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!",objectivesText="Enter Blackrock Stronghold and take out the leader of the Dark Horde. Progress: Have you taken them out?",starts={{npcID=242120,x=0.334,y=0.484,zoneID=46}},ends={{npcID=242120,x=0.334,y=0.484,zoneID=46}},coords={x=0.334,y=0.484,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Warriors Without a Warlord"},
[86839] = {id=86839,name="Relics of Light's Hope",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time. There are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there. Arator trained there as well. Perhaps the solution to his pain could also be found within.",objectivesText="Meet Lord Maxwell Tyrosus at Light's Hope Chapel.",starts={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.528,y=0.552,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Relics of Light's Hope"},
[86840] = {id=86840,name="Flickering Hope",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="Normally, $p, paladins from Light's Hope hold back the Scourge in the immediate area around the chapel, but they've all been called to fight the Void. As a result, Scourge forces have greatly increased their numbers around the chapel. We've managed to hold the line so far, but only with the help of Darion and the Ebon Blade. Give us some room to breathe--defeat as many of them as you can.",objectivesText="Kill Scourge forces around Light's Hope Chapel. Progress: We can't hold back the undead forever, <name>.",starts={{npcID=237594,x=0.738,y=0.536,zoneID=139}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.738,y=0.536,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Flickering Hope"},
[86841] = {id=86841,name="Relics of Paladins Past",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=139,mapID=23,description="Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay. Now that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.",objectivesText="Gather 5 relics from the Sanctum of Light. Progress: Countless great heroes are interred under the chapel, <name>. Hopefully their relics can be of aid to those at the Sunwell.",starts={{npcID=237594,x=0.738,y=0.536,zoneID=139}},ends={{npcID=237594,x=0.738,y=0.536,zoneID=139}},coords={x=0.738,y=0.536,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Relics of Paladins Past"},
[86842] = {id=86842,name="Scarlet Power",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator 's state of mind, I'm hesitant to go there. Hmph... No sense in avoiding it. We must all face up to the fact that the Scarlet Crusade calls upon the power of the Light, and has for decades.",objectivesText="Meet Alonsus Faol at Scarlet Monastery. Progress: When it comes to reclaiming relics of the Light from the Scarlet Crusade, there's no better time than now, <name>.",starts={{npcID=237601,x=0.738,y=0.534,zoneID=139}},ends={{mapID=23,npcID=237601,x=0.738,y=0.535}},coords={x=0.738,y=0.534,source="quest_giver",zoneID=139},questType="world",worldTaskTitle="Scarlet Power"},
[86843] = {id=86843,name="Light Miswielded",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="The Scarlet Crusade has been wielding the Light for its evil purposes for decades, $p. I'm disappointed to see how many forces they still have here. Still, the Light responds to them, just as it does to us. We're here to get their relics to help the Sunwell, but while we're here, let's cleanse this place of their dark influence.",objectivesText="Defeat Scarlet Crusade members. Progress: Have you dealt with the Scarlet threat, <name>?",starts={{npcID=237602,mapID=2438,x=0.473153,y=0.907505}},ends={{npcID=237602,mapID=2438,x=0.473153,y=0.907505}},coords={source="quest_giver",mapID=2438,x=0.473153,y=0.907505},questType="world",worldTaskTitle="Light Miswielded"},
[86844] = {id=86844,name="Light Repurposed",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=85,mapID=2438,description="Leaders of the Crusade have channeled the Light through their weapons every day for years. While their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need. As you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.",objectivesText="Recover Meyer's Rod of Castigation , Aelyse's Gleaming Falchion , and Benthar's Scarlet Spire . Progress: What artifacts have you found here, <name>?",starts={{npcID=237602,mapID=2438,x=0.473153,y=0.907505}},ends={{npcID=237602,mapID=2438,x=0.473153,y=0.907505}},coords={source="quest_giver",mapID=2438,x=0.473153,y=0.907505},questType="world",worldTaskTitle="Light Repurposed"},
[86845] = {id=86845,name="The Sunwalker Path",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=15969,mapID=2372,description="I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light. I would like to consult with the wisest person I know, Sunwalker Dezco . I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.",objectivesText="Meet with Sunwalker Dezco in Hammerfall. Progress: Welcome, <name>. There's plenty to do here if you're willing!",starts={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},ends={{npcID=245186,x=0.69,y=0.376,zoneID=45}},coords={x=0.526,y=0.558,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="The Sunwalker Path"},
[86846] = {id=86846,name="Resupplying Our Suppliers",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, the people of Hammerfall were attacked not so long ago by saboteurs from a group called the Red Dawn. I am working to help them recover and rebuild from the attack with my fellow Sunwalkers: Malu and Nadura. One thing they have been doing is gathering supplies needed by Hammerfall's crafters from various sources. If you could deliver these supplies, it would be a great help.",objectivesText="Aid the people of Hammerfall in their recovery. Progress: Have you distributed the supplies, <name>?",starts={{npcID=245186,x=0.69,y=0.376,zoneID=45}},ends={{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.69,y=0.376,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="Resupplying Our Suppliers"},
[88771] = {id=88771,name="Loaknit Alphas!",expansion=0,mapID=13,questType="world",worldTaskTitle="Loaknit Alphas!"},
[88772] = {id=88772,name="Mammoth Remnants!",expansion=0,mapID=13,questType="world",worldTaskTitle="Mammoth Remnants!"},
[88804] = {id=88804,name="Defeat the Mineraw!",expansion=0,mapID=13,questType="world",worldTaskTitle="Defeat the Mineraw!"},
[89338] = {id=89338,name="Gathering Plowshares",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, now that Hammerfall can expect peace with Stromgarde, there's a lot more use in being able to farm and craft than in fighting. So, we've been gathering old weapons from past skirmishes to make into tools for the people of Hammerfall. Would you and Arator be willing to give me a hand?",objectivesText="Gather 4 Fallen Longswords and 4 Forgotten Skullcleavers . Progress: The weapons we gather will help reforge Hammerfall's future, <name>.",starts={{npcID=247299,x=0.686,y=0.322,zoneID=45}},ends={{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.686,y=0.322,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="Gathering Plowshares"},
[90128] = {id=90128,name="Miscreant Baras!",expansion=0,mapID=13,questType="world",worldTaskTitle="Miscreant Baras!"},
[90961] = {id=90961,name="Stranger in a New Land",level=10,requiredLevel=10,faction="both",expansion=0,zoneID=1637,mapID=85,description=", I see you now for who you are. You are dedicated not just to our people, but to the world. The goddess has acknowledged you as well, and I can not recall such an event--not even Orweyna's ceremony was so eventful. This is where your story begins. It is time for you to take the first steps of your journey.",objectivesText="With the conclusion of the ceremony, it is now time to start your journey.",starts={{npcID=245097,x=0.318,y=0.274,zoneID=15355}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519},{npcID=133407,x=0.394,y=0.792,zoneID=1637}},coords={x=0.318,y=0.274,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Stranger in a New Land"},
[91000] = {id=91000,name="A Humble Servant",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=45,mapID=2372,description="$p, residents of Hammerfall have been focused on daily life, defense, and survival over the past months. They have not had sufficient time, or frankly numbers, to address all the harms that were done. There is much we can do to help them get back on their feet. I know this is humble work, but it makes a very real difference to the orcs who live here.",objectivesText="Aid the people of Hammerfall in their recovery. Progress: There is much to do, <name>.",starts={{npcID=245186,x=0.69,y=0.376,zoneID=45}},ends={{npcID=245186,x=0.69,y=0.376,zoneID=45},{npcID=247299,x=0.686,y=0.322,zoneID=45}},coords={x=0.69,y=0.376,source="quest_giver",zoneID=45},questType="world",worldTaskTitle="A Humble Servant"},
[91391] = {id=91391,name="Still Scouting",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there. Meet up with him and see what kind of trouble you can cause.",objectivesText="Meet Kurdran at Blackrock Mountain.",starts={{npcID=237224,x=0.334,y=0.486,zoneID=46}},ends={{npcID=237268,x=0.212,y=0.398,zoneID=46}},coords={x=0.334,y=0.486,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Still Scouting"},
[91429] = {id=91429,name="Mausoloa Sarcophagi!",expansion=0,mapID=13,questType="world",worldTaskTitle="Mausoloa Sarcophagi!"},
[91726] = {id=91726,name="Unstoppable Force",level=83,requiredLevel=83,faction="both",expansion=0,zoneID=46,mapID=36,description="This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain. Many fought on this field. Many didn't make it. Lothar... Let me tell ye what happened all those years ago.",objectivesText="Ask Kurdran about the events of that day. Progress: It was such a dark day, <name>. Painful to remember.",starts={{npcID=248250,x=0.368,y=0.51,zoneID=46}},ends={{npcID=248250,x=0.368,y=0.51,zoneID=46}},coords={x=0.368,y=0.51,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="Unstoppable Force"},
[92715] = {id=92715,name="By Invitation Only?",level=80,requiredLevel=80,faction="horde",expansion=0,zoneID=15969,mapID=86,description="Fancy yourself a Brawl'gar contender do you, ? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.",objectivesText="Talk to Alton Philips near the Brawl'gar Arena.",starts={{npcID=252857,x=0.46,y=0.608,zoneID=1637},{npcID=252857,x=0.514,y=0.4,zoneID=14771},{npcID=252857,x=0.43,y=0.838,zoneID=15969}},ends={{npcID=252933,x=0.734,y=0.316,zoneID=1637}},coords={x=0.46,y=0.608,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="By Invitation Only?"},
[92845] = {id=92845,name="By Invitation Only?",level=80,requiredLevel=80,faction="alliance",expansion=0,zoneID=2257,mapID=84,description="Fancy yourself a Brawlpub contender do you, ? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.",objectivesText="Talk to Pick Butterworth near Bizmo's Brawlpub in the Deeprun Tram .",starts={{npcID=253181,x=0.666,y=0.718,zoneID=1519},{npcID=253181,x=0.51,y=0.434,zoneID=14771},{npcID=253181,x=0.43,y=0.77,zoneID=15969}},ends={{mapID=84,npcID=253181,x=0.664667,y=0.716667}},coords={x=0.666,y=0.718,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="By Invitation Only?"},
[94210] = {id=94210,name="Feathering the Nest",level=0,requiredLevel=0,faction="both",expansion=0,zoneID=15524,mapID=2352,description="A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.",objectivesText="Learn where to obtain Decor. Progress: Have you met all the local vendors? They have some great furnishings available.",starts={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},ends={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},coords={x=0.53,y=0.4,source="quest_giver",zoneID=16105},questType="world",worldTaskTitle="Feathering the Nest",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[94379] = {id=94379,name="This Old Hearth",level=0,requiredLevel=0,faction="both",expansion=0,zoneID=15524,mapID=2351,description="It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here. Head on over to our general contractor for next steps.",objectivesText="Level up your house. Progress: Did you get your house upgraded?",starts={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},ends={{npcID=233063,x=0.53,y=0.4,zoneID=16105},{npcID=233708,x=0.552,y=0.576,zoneID=15524}},coords={x=0.53,y=0.4,source="quest_giver",zoneID=16105},questType="world",worldTaskTitle="This Old Hearth",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[94444] = {id=94444,name="Choose a Path",level=10,requiredLevel=10,faction="horde",expansion=0,zoneID=1519,mapID=85,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",objectivesText="Talk to Chromie in Orgrimmar. Progress: Greetings, <name>. Has Orgrimmar been to your liking so far?",starts={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=257671,x=0.4,y=0.792,zoneID=1637}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="world",worldTaskTitle="Choose a Path"},
[94445] = {id=94445,name="Choose a Path",level=10,requiredLevel=10,faction="alliance",expansion=0,zoneID=1637,mapID=84,description="Welcome to Stormwind, . I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, !",objectivesText="Talk to Chromie in Stormwind City.",starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=249187,x=0.538,y=0.126,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="world",worldTaskTitle="Choose a Path"},
